#[no_mangle]
pub extern "C" fn xmlNextChar(mut ctxt: xmlParserCtxtPtr) {
    unsafe {
        // SAFETY: All raw pointer dereferences below are guarded by the same
        // preconditions as the original function: `ctxt` and `(*ctxt).input`
        // are checked for null before use, and buffer accesses are preceded by
        // availability checks matching the original logic.
        if ctxt.is_null()
            || (*ctxt).instate as c_int == XML_PARSER_EOF as c_int
            || (*ctxt).input.is_null()
        {
            return;
        }

        let input = (*ctxt).input;
        let mut avail = (*input).end.offset_from((*input).cur) as c_long as size_t;
        if avail < INPUT_CHUNK as size_t {
            xmlParserGrow(ctxt);
            if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                return;
            }
            let input2 = (*ctxt).input;
            if (*input2).cur >= (*input2).end {
                return;
            }
            avail = (*input2).end.offset_from((*input2).cur) as c_long as size_t;
        }

        let input = (*ctxt).input;
        let cur_ptr = (*input).cur;
        let cur = cur_ptr as *const c_uchar;
        let c = *cur as c_int;

        if c < 0x80 {
            if c == '\n' as i32 {
                (*input).cur = cur_ptr.offset(1);
                (*input).line += 1;
                (*input).col = 1;
            } else if c == '\r' as i32 {
                let step = if *cur.offset(1) as c_int == '\n' as i32 { 2 } else { 1 };
                (*input).cur = cur_ptr.offset(step as isize);
                (*input).line += 1;
                (*input).col = 1;
                return;
            } else {
                (*input).cur = cur_ptr.offset(1);
                (*input).col += 1;
            }
            return;
        }

        (*input).col += 1;

        let valid = if avail < 2 || (*cur.offset(1) as c_int & 0xc0) != 0x80 {
            0isize
        } else if c < 0xe0 {
            if c < 0xc2 { 0 } else { 2 }
        } else {
            let val: c_uint = ((c << 8) | *cur.offset(1) as c_int) as c_uint;
            if avail < 3 || (*cur.offset(2) as c_int & 0xc0) != 0x80 {
                0
            } else if c < 0xf0 {
                if val < 0xe0a0 || (val >= 0xeda0 && val < 0xee00) {
                    0
                } else {
                    3
                }
            } else if avail < 4 || (*cur.offset(3) as c_int & 0xc0) != 0x80 {
                0
            } else if val < 0xf090 || val >= 0xf490 {
                0
            } else {
                4
            }
        };

        if valid != 0 {
            (*input).cur = cur_ptr.offset(valid);
            return;
        }

        if (*input).flags as c_uint & XML_INPUT_ENCODING_ERROR == 0 {
            if ctxt.is_null()
                || (*ctxt).input.is_null()
                || ((*(*ctxt).input).end.offset_from((*(*ctxt).input).cur) as c_long) < 4
            {
                __xmlErrEncoding(
                    ctxt,
                    XML_ERR_INVALID_CHAR,
                    b"Input is not proper UTF-8, indicate encoding !\n\0" as *const u8
                        as *const c_char,
                    ::core::ptr::null::<xmlChar>(),
                    ::core::ptr::null::<xmlChar>(),
                );
            } else {
                let mut buffer: [c_char; 150] = [0; 150];
                snprintf(
                    &raw mut buffer as *mut c_char,
                    149 as size_t,
                    b"Bytes: 0x%02X 0x%02X 0x%02X 0x%02X\n\0" as *const u8 as *const c_char,
                    *(*(*ctxt).input).cur.offset(0) as c_int,
                    *(*(*ctxt).input).cur.offset(1) as c_int,
                    *(*(*ctxt).input).cur.offset(2) as c_int,
                    *(*(*ctxt).input).cur.offset(3) as c_int,
                );
                __xmlErrEncoding(
                    ctxt,
                    XML_ERR_INVALID_CHAR,
                    b"Input is not proper UTF-8, indicate encoding !\n%s\0" as *const u8
                        as *const c_char,
                    &raw mut buffer as *mut c_char as *mut xmlChar,
                    ::core::ptr::null::<xmlChar>(),
                );
            }
            (*input).flags = ((*input).flags as c_uint | XML_INPUT_ENCODING_ERROR) as c_int;
        }

        (*input).cur = (*input).cur.offset(1);
    }
}

